function agentGetContext() {
  const a = state.analysis;
  const directives = state.imageDirectives.filter(d=>d.active).map(d=>d.text);
  const customInstructions = Object.entries(state.sectionInstructions).filter(([,v])=>v).map(([k,v])=>`${k}: "${v}"`);
  const cfg = state.modelConfig;
  return `현재 앱 상태:
- 제품: ${a ? `${a.product_name} (${a.category})` : '없음'}
- LLM 모델: ${cfg.llmProvider}/${cfg.llmModel}
- 이미지 모델: ${cfg.imageModel}
- 활성 이미지 제약 조건 (${directives.length}개): ${directives.length ? directives.map((d,i)=>`\n  ${i+1}. ${d}`).join('') : '없음'}
- 섹션별 커스텀 지시사항 (${customInstructions.length}개): ${customInstructions.length ? customInstructions.join(', ') : '없음'}
- 생성된 섹션: ${Object.keys(state.sectionContents).length}/15개`;
}

function agentGetSystemPrompt() {
  return `당신은 한국어 이커머스 상세페이지 자동 생성 앱을 완전히 제어하는 AI 어시스턴트입니다.
사용자의 자연어 명령을 이해하고 앱 설정을 직접 변경합니다.

${agentGetContext()}

사용 가능한 도구 (actions 배열에 포함):
- add_directive: 이미지 생성 제약 추가 → {"tool":"add_directive","text":"English constraint","label":"한국어 설명"}
- remove_directive: 제약 삭제 (텍스트 부분 일치) → {"tool":"remove_directive","match":"삭제할 텍스트"}
- clear_directives: 모든 제약 삭제 → {"tool":"clear_directives"}
- set_section_instruction: 섹션 커스텀 지시사항 설정 → {"tool":"set_section_instruction","sectionId":"header","text":"지시사항"}
- clear_section_instruction: 섹션 지시사항 삭제 → {"tool":"clear_section_instruction","sectionId":"header"}
- set_image_model: 이미지 모델 변경 → {"tool":"set_image_model","modelId":"gemini-3.1-flash-image"}
- set_llm_model: LLM 모델 변경 → {"tool":"set_llm_model","provider":"gemini","modelId":"gemini-3.5-flash"}
- update_analysis: 분석 필드 수정 → {"tool":"update_analysis","field":"product_name","value":"새 이름"}
- regenerate_section: 섹션 재생성 트리거 → {"tool":"regenerate_section","sectionId":"header"}

응답 형식 (반드시 이 JSON으로만 응답):
{
  "reply": "사용자에게 보여줄 한국어 응답 (2-3문장, 친절하게)",
  "actions": []
}

규칙:
- 반드시 JSON으로만 응답. 다른 텍스트 없음.
- reply는 항상 한국어.
- 명령이 없는 질문(현재 상태 등)은 actions 빈 배열로 답변.
- 확실하지 않은 명령은 actions 없이 질문으로 되물음.`;
}

async function executeAgentActions(actions) {
  const results = [];
  for (const action of actions) {
    try {
      if (action.tool === 'add_directive') {
        const id = Date.now() + Math.random();
        state.imageDirectives.push({ id, original: action.label || action.text, text: action.text, active: true });
        saveImageDirectives();
        results.push({ ...action, label: action.label || `제약 추가: "${action.text.slice(0,40)}"` });

      } else if (action.tool === 'remove_directive') {
        const before = state.imageDirectives.length;
        state.imageDirectives = state.imageDirectives.filter(d =>
          !d.text.toLowerCase().includes((action.match||'').toLowerCase()) &&
          !d.original.toLowerCase().includes((action.match||'').toLowerCase())
        );
        saveImageDirectives();
        results.push({ ...action, label: `제약 삭제 (${before - state.imageDirectives.length}개)` });

      } else if (action.tool === 'clear_directives') {
        state.imageDirectives = [];
        saveImageDirectives();
        results.push({ ...action, label: '모든 이미지 제약 초기화' });

      } else if (action.tool === 'set_section_instruction') {
        state.sectionInstructions[action.sectionId] = action.text;
        saveSectionInstructions(state.sectionInstructions);
        results.push({ ...action, label: `섹션 [${action.sectionId}] 지시사항 설정` });

      } else if (action.tool === 'clear_section_instruction') {
        delete state.sectionInstructions[action.sectionId];
        saveSectionInstructions(state.sectionInstructions);
        results.push({ ...action, label: `섹션 [${action.sectionId}] 지시사항 삭제` });

      } else if (action.tool === 'set_image_model') {
        state.modelConfig.imageModel = action.modelId;
        saveModelConfig(state.modelConfig);
        results.push({ ...action, label: `이미지 모델 → ${action.modelId}` });

      } else if (action.tool === 'set_llm_model') {
        state.modelConfig.llmProvider = action.provider;
        state.modelConfig.llmModel = action.modelId;
        state.modelConfig = normalizeModelConfig(state.modelConfig);
        saveModelConfig(state.modelConfig);
        results.push({ ...action, label: `LLM → ${state.modelConfig.llmProvider}/${state.modelConfig.llmModel}` });

      } else if (action.tool === 'update_analysis') {
        if (state.analysis) {
          state.analysis[action.field] = action.value;
          savePersistentState();
          results.push({ ...action, label: `분석 데이터 [${action.field}] → "${action.value}"` });
        }

      } else if (action.tool === 'regenerate_section') {
        results.push({ ...action, label: `섹션 [${action.sectionId}] 재생성 시작` });
        // 비동기로 실행 (채팅 응답 후에)
        setTimeout(() => generateSingleSection(action.sectionId), 500);
      }
    } catch(e) {
      console.warn('Action failed:', action, e);
    }
  }
  return results;
}

function agentLastBubble() {
  const bubbles = document.querySelectorAll('.agent-bubble.assistant');
  return bubbles[bubbles.length - 1] || null;
}
function agentSetStatus(text) {
  const el = agentLastBubble()?.querySelector('[data-agent-status]');
  if (el) el.textContent = text;
}
function agentAddStep(label, done) {
  const msg = state.agentMessages[state.agentMessages.length - 1];
  if (!msg || msg.role !== 'assistant') return;
  msg.steps = msg.steps || [];
  msg.steps.push({ label, done });

  const stepsEl = agentLastBubble()?.querySelector('[data-agent-steps]');
  if (!stepsEl) return;
  const spinnerRow = stepsEl.querySelector('[data-agent-status]')?.parentElement;
  const newRow = document.createElement('div');
  newRow.style.cssText = `display:flex;align-items:center;gap:6px;font-size:11px;color:${done?'var(--ok)':'var(--primary-h)'};font-family:monospace;padding:3px 0;border-bottom:1px solid var(--border)`;
  newRow.dataset.stepRow = '';
  newRow.innerHTML = `<span class="material-icons-outlined" style="font-size:13px">${done?'check_circle':'pending'}</span><span>${label}</span>`;
  if (spinnerRow) stepsEl.insertBefore(newRow, spinnerRow);
  else stepsEl.appendChild(newRow);
  scrollAgentToBottom();
}
function agentMarkLastStepDone() {
  const stepsEl = agentLastBubble()?.querySelector('[data-agent-steps]');
  if (!stepsEl) return;
  const rows = [...stepsEl.querySelectorAll('[data-step-row=""]')];
  const last = rows[rows.length - 1];
  if (last) {
    last.style.color = 'var(--ok)';
    const icon = last.querySelector('.material-icons-outlined');
    if (icon) icon.textContent = 'check_circle';
  }
}

async function agentSendMessage(userText) {
  if (!userText.trim() || state.agentStreaming) return;

  state.agentMessages.push({ role: 'user', content: userText });
  state.agentStreaming = true;
  const assistantIdx = state.agentMessages.length;
  state.agentMessages.push({ role: 'assistant', content: '', steps: [], done: false });
  render();
  scrollAgentToBottom();

  try {
    let llm;
    try { llm = getLLMClient(); } catch(e) {
      state.agentMessages[assistantIdx].content = `⚠️ LLM 연결 없음: ${e.message}`;
      state.agentMessages[assistantIdx].done = true;
      state.agentStreaming = false;
      render(); return;
    }

    // ① LLM 호출
    agentSetStatus('명령 분석 중...');
    const systemPrompt = agentGetSystemPrompt();
    const history = state.agentMessages.slice(0, -1);
    let rawResponse = '';
    if (llm instanceof GeminiAPI) rawResponse = await agentCallGemini(llm, systemPrompt, history);
    else if (llm instanceof OpenAIAPI) rawResponse = await agentCallOpenAI(llm, systemPrompt, history);

    let parsed = { reply: '', actions: [] };
    try {
      const cleaned = rawResponse.replace(/^```json\s*/,'').replace(/^```\s*/,'').replace(/\s*```$/,'').trim();
      parsed = JSON.parse(cleaned);
    } catch(e) { parsed = { reply: rawResponse, actions: [] }; }

    // ② 액션 실행 — 각 스텝을 DOM에 실시간 표시
    if (parsed.actions && parsed.actions.length > 0) {
      agentSetStatus('처리 중...');
      for (const action of parsed.actions) {
        const label = agentActionLabel(action);
        agentAddStep(label, false);
        await new Promise(r => setTimeout(r, 100));
        await executeAgentActions([action]);
        agentMarkLastStepDone();
        await new Promise(r => setTimeout(r, 80));
      }
    }

    // ③ spinner 제거 후 타이프라이터
    const bubble = agentLastBubble();
    const spinnerRow = bubble?.querySelector('[data-agent-status]')?.parentElement;
    if (spinnerRow) spinnerRow.remove();

    const replyText = parsed.reply || '';
    state.agentMessages[assistantIdx].content = replyText;

    if (bubble && replyText) {
      const twDiv = document.createElement('div');
      twDiv.style.cssText = 'white-space:pre-wrap;margin-top:6px;font-size:13px;line-height:1.6';
      const twSpan = document.createElement('span');
      const cursor = document.createElement('span');
      cursor.className = 'agent-cursor';
      twDiv.appendChild(twSpan);
      twDiv.appendChild(cursor);
      bubble.appendChild(twDiv);

      for (let i = 0; i <= replyText.length; i++) {
        twSpan.textContent = replyText.slice(0, i);
        if (i % 4 === 0) scrollAgentToBottom();
        await new Promise(r => setTimeout(r, 14));
      }
      cursor.remove();
    }

    state.agentMessages[assistantIdx].done = true;

  } catch(e) {
    state.agentMessages[assistantIdx].content = `오류가 발생했습니다: ${e.message}`;
    state.agentMessages[assistantIdx].done = true;
  }

  state.agentStreaming = false;
  render();
  scrollAgentToBottom();
}

function agentActionLabel(action) {
  const map = {
    add_directive:            `이미지 제약 추가 → "${(action.text||'').slice(0,50)}"`,
    remove_directive:         `이미지 제약 삭제 → "${action.match||''}"`,
    clear_directives:         '모든 이미지 제약 초기화',
    set_section_instruction:  `섹션 [${action.sectionId}] 지시사항 설정`,
    clear_section_instruction:`섹션 [${action.sectionId}] 지시사항 삭제`,
    set_image_model:          `이미지 모델 변경 → ${action.modelId}`,
    set_llm_model:            `LLM 변경 → ${action.provider}/${action.modelId}`,
    update_analysis:          `분석 데이터 [${action.field}] 수정 → "${action.value}"`,
    regenerate_section:       `섹션 [${action.sectionId}] 재생성 시작`,
  };
  return map[action.tool] || action.tool;
}

async function agentCallGemini(llm, systemPrompt, history) {
  const contents = [
    { role: 'user', parts: [{ text: systemPrompt }] },
    { role: 'model', parts: [{ text: '{"reply":"알겠습니다. 명령을 기다리겠습니다.","actions":[]}' }] },
    ...history.map(m => ({
      role: m.role === 'user' ? 'user' : 'model',
      parts: [{ text: m.content || '{}' }]
    }))
  ];
  const body = { contents, generationConfig: { temperature: 0.3, maxOutputTokens: 1024 } };
  const data = await llm._generateContent(llm.model, body);
  tokenTracker.record(llm.model, data.usageMetadata?.promptTokenCount, data.usageMetadata?.candidatesTokenCount, false, 'AI어시스턴트');
  return data.candidates[0].content.parts[0].text.trim();
}

async function agentCallOpenAI(llm, systemPrompt, history) {
  const messages = [
    { role: 'system', content: systemPrompt },
    ...history.map(m => ({ role: m.role === 'assistant' ? 'assistant' : 'user', content: m.content || '' }))
  ];
  const body = { model: llm.model, messages, temperature: 0.3, max_completion_tokens: 1024 };
  const res = await fetch(`${llm.baseUrl}/chat/completions`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${llm.apiKey}` },
    body: JSON.stringify(body)
  });
  const data = await res.json();
  if (data.error) throw new Error(data.error.message);
  tokenTracker.record(llm.model, data.usage?.prompt_tokens, data.usage?.completion_tokens, false, 'AI어시스턴트');
  return data.choices[0].message.content.trim();
}

function scrollAgentToBottom() {
  setTimeout(() => {
    const el = document.getElementById('agentMsgs');
    if (el) el.scrollTop = el.scrollHeight;
  }, 0);
}

function saveImageDirectives(options = {}) {
  saveJson(STORAGE_KEYS.imageDirectives, state.imageDirectives);
  if (options.skipPersistentState !== true) savePersistentState();
}

async function addImageDirective(rawText) {
  if (!rawText.trim()) return;
  state.imageDirectiveProcessing = true;
  render();

  let processed = rawText.trim();
  // 설정된 LLM으로 자연어 지시사항 → 이미지 프롬프트 제약 조건으로 변환
  try {
    const llm = getLLMClient();
    const convPrompt = `You are helping convert a user's natural language instruction about image generation into a concise English constraint for an AI image generator.

User instruction (Korean or English): "${rawText}"

Convert this into a short, clear English constraint (1-2 sentences max) that can be appended to an image generation prompt. Be specific and actionable. Return ONLY the constraint text, nothing else.`;

    let result = '';
    if (llm instanceof GeminiAPI) {
      const body = { contents: [{ parts: [{ text: convPrompt }] }], generationConfig: { temperature: 0.2, maxOutputTokens: 150 } };
      const data = await llm._generateContent(llm.model, body);
      result = data.candidates[0].content.parts[0].text.trim();
    } else if (llm instanceof OpenAIAPI) {
      const body = { model: llm.model, messages: [{ role: 'user', content: convPrompt }], max_completion_tokens: 150, temperature: 0.2 };
      const res = await fetch(`${llm.baseUrl}/chat/completions`, { method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${llm.apiKey}` }, body: JSON.stringify(body) });
      const data = await res.json();
      result = data.choices[0].message.content.trim();
    }
    if (result) processed = result;
  } catch(e) {
    console.warn('Directive LLM processing failed, using raw text:', e);
  }

  const directive = { id: Date.now(), original: rawText.trim(), text: processed, active: true };
  state.imageDirectives.push(directive);
  state.imageDirectiveInput = '';
  state.imageDirectiveProcessing = false;
  saveImageDirectives();
  render();
}

let driveService = null;
let tokenClient = null;

// 토큰 자동 갱신 — 사용자 팝업 없이 silent 시도, 실패 시 팝업
function refreshDriveToken() {
  return new Promise((resolve, reject) => {
    const clientId = state.auto.gdClientId || localStorage.getItem('gd_client_id') || '';
    const oauth = window.google?.accounts?.oauth2;
    if (!clientId || !oauth) {
      reject(new Error('Google OAuth 초기화 안 됨'));
      return;
    }
    const client = oauth.initTokenClient({
      client_id: clientId,
      scope: 'https://www.googleapis.com/auth/drive.file https://www.googleapis.com/auth/drive.readonly',
      prompt: '',  // silent 갱신 시도
      callback: (resp) => {
        if (resp.error) {
          autoLog('err', '토큰 갱신 실패 — Google Drive 재연결 필요');
          state.auto.driveConnected = false;
          render();
          reject(new Error(resp.error));
          return;
        }
        if (resp.access_token) {
          state.auto.accessToken = resp.access_token;
          state.auto.driveConnected = true;
          if (driveService) {
            driveService.token = resp.access_token;
            driveService.tokenExpiresAt = Date.now() + 3500 * 1000;
          } else {
            driveService = new DriveService(resp.access_token);
          }
          autoLog('ok', '토큰 자동 갱신 완료');
          resolve();
        } else {
          autoLog('err', '토큰 갱신 실패 — Google Drive 재연결 필요');
          state.auto.driveConnected = false;
          render();
          reject(new Error('Token refresh failed'));
        }
      },
    });
    client.requestAccessToken();
  });
}

function initGoogleAuth() {
  const clientId = state.auto.gdClientId || GD_CLIENT_ID;
  if (!clientId) return;
  const oauth = window.google?.accounts?.oauth2;
  if (!oauth) return;
  try {
    tokenClient = oauth.initTokenClient({
      client_id: clientId,
      scope: 'https://www.googleapis.com/auth/drive.file https://www.googleapis.com/auth/drive.readonly',
      callback: (resp) => {
        if (resp.error) {
          autoLog('info', 'Google Drive 자동 재연결 대기 중: ' + resp.error);
          return;
        }
        if (resp.access_token) {
          state.auto.accessToken = resp.access_token;
          state.auto.driveConnected = true;
          driveService = new DriveService(resp.access_token);
          autoLog('info', 'Google Drive 연결 완료');
          render();
        }
      },
    });
    if (!state.auto.driveConnected && !initGoogleAuth._silentAttempted) {
      initGoogleAuth._silentAttempted = true;
      setTimeout(() => {
        try {
          tokenClient?.requestAccessToken({ prompt: '' });
        } catch(e) {
          autoLog('info', 'Google Drive 자동 재연결 대기 중');
        }
      }, 200);
    }
  } catch(e) { console.warn('Google auth init failed:', e); }
}

async function ensureDriveServiceReady() {
  if (driveService) return true;
  try {
    await refreshDriveToken();
    return !!driveService;
  } catch(e) {
    return false;
  }
}

function connectDrive(operationContext = null) {
  if (!runtimeOperationContextIsCurrent(operationContext)) return false;
  const clientId = document.getElementById('gdClientId')?.value.trim() || GD_CLIENT_ID;
  if (!clientId) {
    if (!runtimeOperationContextIsCurrent(operationContext)) return false;
    state.error = 'Google Cloud OAuth Client ID를 입력하세요.';
    render();
    return false;
  }
  if (!runtimeOperationContextIsCurrent(operationContext)) return false;
  localStorage.setItem('gd_client_id', clientId);
  state.auto.gdClientId = clientId;
  try {
    const oauth = window.google?.accounts?.oauth2;
    if (!oauth) throw new Error('Google OAuth 스크립트가 아직 로드되지 않았습니다.');
    tokenClient = oauth.initTokenClient({
      client_id: clientId,
      scope: 'https://www.googleapis.com/auth/drive.file https://www.googleapis.com/auth/drive.readonly',
      callback: (resp) => {
        if (!runtimeOperationContextIsCurrent(operationContext)) return;
        if (resp.error) {
          state.error = `Drive 인증 실패: ${resp.error}`;
          render();
          return;
        }
        state.auto.accessToken = resp.access_token;
        state.auto.driveConnected = true;
        driveService = new DriveService(resp.access_token);
        autoLog('info', 'Google Drive 연결 완료');
        render();
      },
    });
    tokenClient.requestAccessToken();
    return true;
  } catch(e) {
    if (!runtimeOperationContextIsCurrent(operationContext)) return false;
    state.error = `Google 인증 오류: ${e.message}`;
    render();
    return false;
  }
}

// ════════════════════════════════════════════════════════════════
// AUTOMATION LOG
// ════════════════════════════════════════════════════════════════
const autoLogs = [];
function autoLog(type, msg) {
  const t = new Date().toLocaleTimeString('ko-KR');
  autoLogs.unshift({ type, msg, time: t });
  if (autoLogs.length > 200) autoLogs.length = 200;
}

function escAttr(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function shortText(value, max = 90) {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  return text.length > max ? `${text.slice(0, Math.max(0, max - 1))}…` : text;
}

function formatServerDriveMessage(serverDrive) {
  const message = String(serverDrive?.message || '').trim();
  if (!message) return '';
  if (message.includes('Drive scope is missing in ADC')) {
    const command = serverDrive?.loginCommand || (message.match(/Run this command and re-login:\s*(.+)$/i)?.[1] || '');
    return `서버 Google 로그인(ADC)에 Google Drive 권한이 빠져 있습니다. 자동화 서버가 Drive 출력 이미지와 생성 프롬프트 기록을 읽으려면 아래 gcloud 재로그인이 필요합니다.${command ? `\n\n${command}` : ''}`;
  }
  return message;
}

function parsePositiveInt(value, fallback, min, max) {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.max(min, Math.min(max, Math.round(n)));
}

async function fetchServerAutomationConfig() {
  const base = saveServerAutomationApiBase(state.auto.serverApiBase);
  captureServerDraftCutsFromDom({ forceSave: true });
  state.auto.serverApiBase = base;
  state.auto.serverLoading = true;
  state.auto.serverError = '';
  render();
  try {
    assertServerAutomationApiBaseAllowed(base);
    const res = await fetch(`${base}/pdp/automation/config`);
    const data = await res.json();
    if (!res.ok || !data?.ok) {
      throw new Error(data?.message || data?.error || '자동화 설정 조회 실패');
    }
    state.auto.serverConfig = data;
    state.auto.serverStatus = data.status || null;
    // 서버 커스텀 컷은 빈 로컬 슬롯만 보충한다. 로컬 입력은 서버 응답으로 덮어쓰지 않는다.
    const serverCuts = data?.profiles?.['image-cuts']?.customCuts;
    if (Array.isArray(serverCuts) && serverCuts.some(c => c?.prompt?.trim())) {
      const serverCount = countDraftCutPrompts(serverCuts);
      const localCount = countDraftCutPrompts(state.auto.draftCuts);
      if (!state.auto.draftCutsFromServer || serverCount > localCount) {
        const merged = mergeServerDraftCutsFromConfig(serverCuts);
        if (merged.changed) autoLog('ok', `서버 프롬프트를 빈 슬롯에만 보충했습니다. 현재 ${merged.count}칸`);
        state.auto.draftCutsFromServer = true;
      }
    }
    autoLog('ok', '서버 자동화 상태를 불러왔습니다.');
  } catch(e) {
    state.auto.serverError = e.message || String(e);
    autoLog('err', `서버 자동화 연결 실패: ${state.auto.serverError}`);
  } finally {
    state.auto.serverLoading = false;
    render();
  }
}

async function updateServerAutomationProfiles(profilePatch) {
  const base = saveServerAutomationApiBase(state.auto.serverApiBase);
  captureServerDraftCutsFromDom({ forceSave: true });
  state.auto.serverApiBase = base;
  state.auto.serverLoading = true;
  state.auto.serverError = '';
  render();
  try {
    assertServerAutomationApiBaseAllowed(base);
    const res = await fetch(`${base}/pdp/automation/config`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ profiles: profilePatch })
    });
    const data = await res.json();
    if (!res.ok || !data?.ok) {
      throw new Error(data?.message || data?.error || '자동화 설정 저장 실패');
    }
    state.auto.serverConfig = data;
    state.auto.serverStatus = data.status || null;
    autoLog('ok', '서버 자동화 설정을 저장했습니다.');
  } catch(e) {
    state.auto.serverError = e.message || String(e);
    autoLog('err', `서버 자동화 저장 실패: ${state.auto.serverError}`);
  } finally {
    state.auto.serverLoading = false;
    render();
  }
}

async function runServerAutomationMode(mode) {
  const base = saveServerAutomationApiBase(state.auto.serverApiBase);
  captureServerDraftCutsFromDom({ forceSave: true });
  state.auto.serverApiBase = base;
  state.auto.serverError = '';

  // 실행 전 현재 설정(폴더ID, 프롬프트, 모델)을 서버에 먼저 저장 — enabled는 현재 상태 유지
  try {
    assertServerAutomationApiBaseAllowed(base);
    const modeId = mode === 'image-cuts' ? 'ImageCuts' : 'DetailPage';
    const currentProfile = state.auto.serverConfig?.profiles?.[mode] || {};
    const profileUpdate = {
      enabled: !!currentProfile.enabled,
      inputFolderId: extractFolderId(document.getElementById(`serverInput${modeId}`)?.value?.trim() || ''),
      sourceDoneFolderId: extractFolderId(document.getElementById(`serverDone${modeId}`)?.value?.trim() || ''),
      outputFolderId: extractFolderId(document.getElementById(`serverOutput${modeId}`)?.value?.trim() || ''),
      pollIntervalSeconds: parsePositiveInt(document.getElementById(`serverPoll${modeId}`)?.value, 120, 30, 3600),
      maxFilesPerRun: parsePositiveInt(document.getElementById(`serverMax${modeId}`)?.value, 1, 1, 20),
      imageModel: document.getElementById(`serverModel${modeId}`)?.value || currentProfile.imageModel || 'gemini-3.1-flash-image',
      outputImageSize: document.getElementById(`serverResolution${modeId}`)?.value || null
    };
    if (mode === 'image-cuts') {
      profileUpdate.customCuts = state.auto.draftCuts.map(c => ({label: c.label, prompt: c.prompt}));
    }
    const saveRes = await fetch(`${base}/pdp/automation/config`, {
      method: 'PUT',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({profiles: {[mode]: profileUpdate}})
    });
    const saveData = await saveRes.json();
    if (saveData?.ok) {
      state.auto.serverConfig = saveData;
      autoLog('ok', '설정을 서버에 저장했습니다.');
    }
  } catch(e) {
    autoLog('err', `설정 저장 실패: ${e.message}`);
  }

  try {
    assertServerAutomationApiBaseAllowed(base);
    const res = await fetch(`${base}/pdp/automation/run`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ mode })
    });
    const data = await res.json();
    if (!res.ok || !data?.ok) {
      throw new Error(data?.message || data?.error || '자동 실행 요청 실패');
    }
    if (data.status) { state.auto.serverStatus = data.status; patchAutomationStatusInPlace(); }
    autoLog('info', data.message || `${mode} 실행을 요청했습니다.`);
    startStatusPolling(base, mode);
  } catch(e) {
    state.auto.serverError = e.message || String(e);
    autoLog('err', `서버 실행 요청 실패: ${state.auto.serverError}`);
  }
}

let _statusPollTimer = null;
function startStatusPolling(base, mode) {
  if (_statusPollTimer) clearInterval(_statusPollTimer);
  _statusPollTimer = setInterval(async () => {
    try {
      const res = await fetch(`${base}/pdp/automation/status`);
      if (!res.ok) return;
      const data = await res.json();
      state.auto.serverStatus = data;
      patchAutomationStatusInPlace();
      const modeStatus = data?.byMode?.[mode];
      if (!modeStatus?.isRunning) {
        clearInterval(_statusPollTimer);
        _statusPollTimer = null;
        autoLog('info', `${mode} 작업이 완료되었습니다.`);
        patchAutomationStatusInPlace();
        fetchAutomationOutputImages(mode, { silent: true }).catch(() => {});
      }
    } catch(e) { /* 무시 */ }
  }, 2000);
}

function automationOutputModeLabel(mode) {
  return mode === 'image-cuts' ? 'Image Cuts' : 'Detail Page';
}

function ensureAutomationOutputBuckets() {
  if (!state.auto.outputImages || typeof state.auto.outputImages !== 'object') state.auto.outputImages = {};
  if (!state.auto.outputImagesLoading || typeof state.auto.outputImagesLoading !== 'object') state.auto.outputImagesLoading = {};
  if (!state.auto.outputImagesError || typeof state.auto.outputImagesError !== 'object') state.auto.outputImagesError = {};
}

function automationOutputImagesForMode(mode) {
  ensureAutomationOutputBuckets();
  return Array.isArray(state.auto.outputImages[mode]) ? state.auto.outputImages[mode] : [];
}

async function fetchAutomationOutputImages(mode = 'image-cuts', options = {}) {
  ensureAutomationOutputBuckets();
  const base = saveServerAutomationApiBase(state.auto.serverApiBase);
  state.auto.serverApiBase = base;
  state.auto.outputImagesLoading[mode] = true;
  state.auto.outputImagesError[mode] = '';
  if (!options.silent && state.step === 'automation') render();
  try {
    assertServerAutomationApiBaseAllowed(base);
    const res = await fetch(`${base}/pdp/automation/output-images?mode=${encodeURIComponent(mode)}&limit=12`);
    const data = await res.json().catch(() => ({}));
    if (!res.ok || !data?.ok) {
      throw new Error(data?.error || data?.message || 'Drive 출력 이미지를 불러오지 못했습니다.');
    }
    state.auto.outputImages[mode] = Array.isArray(data.images) ? data.images : [];
    state.auto.outputImagesError[mode] = '';
    if (state.auto.outputImages[mode].length) {
      autoLog('ok', `${automationOutputModeLabel(mode)} 최근 출력 ${state.auto.outputImages[mode].length}장을 불러왔습니다.`);
    }
  } catch(e) {
    state.auto.outputImagesError[mode] = e.message || String(e);
    if (!options.silent) autoLog('err', `${automationOutputModeLabel(mode)} 출력 미리보기 실패: ${state.auto.outputImagesError[mode]}`);
  } finally {
    state.auto.outputImagesLoading[mode] = false;
    if (state.step === 'automation') render();
  }
}

function openAutomationOutputPreview(mode, index) {
  const image = automationOutputImagesForMode(mode)[Number(index)];
  if (!image?.dataUrl) {
    autoLog('err', '크게 볼 출력 이미지가 없습니다.');
    return;
  }
  const promptLabel = image.promptLabel || image.sectionName || '프롬프트 이름 없음';
  const promptText = image.prompt || '프롬프트 기록 없음';
  document.getElementById('automationOutputPreviewOverlay')?.remove();
  const overlay = document.createElement('div');
  overlay.id = 'automationOutputPreviewOverlay';
  overlay.className = 'factory-asset-preview-overlay';
  overlay.innerHTML = `
    <div class="factory-asset-preview-modal" role="dialog" aria-modal="true" onclick="event.stopPropagation()">
      <div class="factory-asset-preview-head">
        <div class="factory-asset-preview-title">${escapeHtml(image.name || 'Drive 출력 이미지')}</div>
        <div class="factory-stage-actions">
          <button class="btn-sm" id="automationOutputPreviewClose" type="button">닫기</button>
        </div>
      </div>
      <div class="factory-asset-preview-body">
      <img src="${escAttr(image.dataUrl)}" alt="${escAttr(image.name || 'Drive 출력 이미지')}" loading="lazy" decoding="async">
        <div style="margin-top:12px;padding:12px;border:1px solid var(--border);border-radius:10px;background:var(--bg-input)">
          <div style="font-size:12px;color:var(--text-m);margin-bottom:4px">생성 프롬프트</div>
          <div style="font-size:14px;font-weight:700;color:var(--text);margin-bottom:6px">${escapeHtml(promptLabel)}</div>
          <div style="font-size:13px;color:var(--text-d);line-height:1.5;white-space:pre-wrap">${escapeHtml(promptText)}</div>
        </div>
      </div>
    </div>`;
  const close = () => overlay.remove();
  overlay.onclick = close;
  document.body.appendChild(overlay);
  document.getElementById('automationOutputPreviewClose')?.addEventListener('click', close);
}

function renderAutomationOutputPreview(mode) {
  ensureAutomationOutputBuckets();
  const images = automationOutputImagesForMode(mode);
  const loading = !!state.auto.outputImagesLoading[mode];
  const error = state.auto.outputImagesError[mode] || '';
  const modeLabel = automationOutputModeLabel(mode);
  return `<section class="auto-output-panel">
    <div class="auto-output-head">
      <div>
        <div class="auto-output-title">최근 Drive 출력 미리보기</div>
        <div class="auto-output-sub">Drive 저장은 그대로 유지하고, 최근 출력 이미지만 앱 안에서 작게 확인합니다.</div>
      </div>
      <button class="btn-sm" type="button" data-auto-output-refresh="${escAttr(mode)}">${loading ? '불러오는 중...' : '최근 출력 새로고침'}</button>
    </div>
    ${error ? `<div class="auto-output-error">${escapeHtml(error)}</div>` : ''}
    ${images.length ? `<div class="auto-output-grid">
      ${images.map((image, index) => {
        const promptLabel = image.promptLabel || image.sectionName || '';
        const promptText = image.prompt || '';
        const promptSummary = promptText ? shortText(promptText, 78) : '프롬프트 기록 없음';
        return `<article class="auto-output-card">
        <button class="auto-output-thumb" type="button" data-auto-output-preview="${escAttr(mode)}:${index}" title="크게 보기">
        <img src="${escAttr(image.dataUrl)}" alt="${escAttr(image.name || `${modeLabel} 출력 ${index + 1}`)}" loading="lazy" decoding="async">
        </button>
        <div class="auto-output-name" title="${escAttr(image.name || '')}">${escapeHtml(image.name || `${modeLabel} 출력 ${index + 1}`)}</div>
        <div class="auto-output-meta" title="${escAttr(promptText || '')}">
          ${escapeHtml(promptLabel ? `${promptLabel} · ${promptSummary}` : promptSummary)}
        </div>
        <div class="auto-output-meta">${escapeHtml(image.createdTime ? new Date(image.createdTime).toLocaleString('ko-KR') : 'Drive 출력')}</div>
      </article>`;
      }).join('')}
    </div>` : `<div class="auto-output-empty">${loading ? 'Drive 출력 폴더를 확인하는 중입니다.' : '아직 불러온 출력 이미지가 없습니다. 실행 후 새로고침을 눌러 확인하세요.'}</div>`}
  </section>`;
}

// 깜빡임 없이 상태/로그만 DOM 직접 업데이트
function patchAutomationStatusInPlace() {
  const status = state.auto.serverStatus;
  const allEvents = status?.recentEvents || [];
  const modes = [['image-cuts','ImageCuts'],['detail-page','DetailPage']];
  for (const [mode, modeId] of modes) {
    const modeStatus = status?.byMode?.[mode];
    const profile = state.auto.serverConfig?.profiles?.[mode];
    const running = !!modeStatus?.isRunning;
    const autoEnabled = !!profile?.enabled;

    const statusEl = document.getElementById(`autoStatusLine-${modeId}`);
    if (statusEl) {
      const pollInterval = profile?.pollIntervalSeconds || 120;
      statusEl.textContent = '상태: ' + (running ? '실행 중' : (autoEnabled ? `자동화 ON (${pollInterval}초 간격)` : '자동화 OFF'));
      statusEl.style.color = running ? 'var(--ok)' : (autoEnabled ? '#4a9eff' : 'var(--text-d)');
    }
    const summaryEl = document.getElementById(`autoSummaryLine-${modeId}`);
    if (summaryEl) summaryEl.textContent = '최근 요약: ' + (modeStatus?.lastSummary || '기록 없음');
    const errorEl = document.getElementById(`autoErrorLine-${modeId}`);
    if (errorEl) {
      const err = modeStatus?.lastError || '';
      errorEl.textContent = err ? '최근 오류: ' + err : '';
      errorEl.style.display = err ? '' : 'none';
    }
    const logEl = document.getElementById(`autoLogBox-${modeId}`);
    if (logEl) logEl.innerHTML = buildEventLogInner(mode, modeStatus, allEvents);
    const autoStartBtn = document.getElementById(`serverAutoStart${modeId}`);
    if (autoStartBtn) autoStartBtn.disabled = autoEnabled;
    const autoStopBtn = document.getElementById(`serverAutoStop${modeId}`);
    if (autoStopBtn) autoStopBtn.disabled = !autoEnabled && !running;
    const runBtn = document.getElementById(`serverRun${modeId}`);
    if (runBtn) runBtn.textContent = running ? '실행 중...' : '즉시 실행';
  }
}

function buildEventLogInner(mode, modeStatus, allEvents) {
  const modeEvents = allEvents.filter(e => e.mode === mode).slice(0, 20);
  if (!modeEvents.length) return '<span style="font-size:11px;color:var(--text-d)">로그 없음</span>';
  return modeEvents.map(e => {
    const t = new Date(e.timestamp).toLocaleTimeString('ko-KR');
    const isErr = e.level === 'error';
    const color = isErr ? 'var(--err)' : 'var(--text-d)';
    const icon = isErr ? '✖' : '●';
    const fileName = e.fileName ? `<span style="color:var(--text-m);margin-left:4px">[${escAttr(e.fileName)}]</span>` : '';
    return `<div style="display:flex;gap:6px;font-size:11px;padding:3px 0;border-bottom:1px solid rgba(255,255,255,0.04)">
      <span style="color:var(--text-m);white-space:nowrap;flex-shrink:0">${t}</span>
      <span style="color:${color};flex-shrink:0">${icon}</span>
      <span style="color:${isErr?'var(--err)':'var(--text)'}">${escAttr(e.message)}${fileName}</span>
    </div>`;
  }).join('');
}

const AUTO_RESOLUTION_OPTIONS = [
  { value: '',   label: '원본 (API 기본값)' },
  { value: '1K', label: '1K (약 1024px)' },
  { value: '2K', label: '2K (약 2048px)' },
  { value: '4K', label: '4K (약 4096px)' }
];

function buildResolutionOptions(current) {
  const cur = current ? String(current) : '';
  return AUTO_RESOLUTION_OPTIONS.map(o =>
    `<option value="${o.value}" ${cur === o.value ? 'selected' : ''}>${o.label}</option>`
  ).join('');
}

// IMAGE_MODELS와 동일한 목록 사용 (중복 제거)
const AUTO_IMAGE_MODELS = IMAGE_MODELS;

function renderServerAutomationModeEditor(mode, title, profile, status) {
  if (!profile) return '';
  const modeId = mode === 'image-cuts' ? 'ImageCuts' : 'DetailPage';
  const running = !!status?.isRunning;
  const summary = status?.lastSummary || '기록 없음';
  const error = status?.lastError || '';
  const autoEnabled = !!profile.enabled;
  const autoStatusText = running ? '실행 중' : (autoEnabled ? `자동화 ON (${profile.pollIntervalSeconds}초 간격)` : '자동화 OFF');
  const autoStatusColor = running ? 'var(--ok)' : (autoEnabled ? '#4a9eff' : 'var(--text-d)');

  const currentModel = profile.imageModel || 'gemini-3.1-flash-image';
  const modelOptions = AUTO_IMAGE_MODELS.map(m =>
    `<option value="${m.id}" ${currentModel === m.id ? 'selected' : ''}>${m.label} — ${m.desc}</option>`
  ).join('');

  const customCutsHtml = mode === 'image-cuts' ? (() => {
    const cuts = state.auto.draftCuts;
    const rows = Array.from({length: 10}, (_, i) => {
      const cut = cuts[i] || {label: '', prompt: ''};
      return `
        <div style="display:grid;grid-template-columns:160px 1fr;gap:8px;align-items:start;margin-bottom:8px">
          <div>
            <div style="font-size:11px;color:var(--text-d);margin-bottom:3px">슬롯 ${i+1} 이름</div>
            <input class="input" id="serverCutLabel${modeId}_${i}" value="${escAttr(cut.label)}" placeholder="예: 메인 배너" style="font-size:12px">
          </div>
          <div>
            <div style="font-size:11px;color:var(--text-d);margin-bottom:3px">프롬프트 <span style="color:var(--ok)">(입력하면 이 슬롯 생성)</span></div>
            <textarea class="input" id="serverCutPrompt${modeId}_${i}" rows="2" placeholder="이미지 생성 프롬프트를 입력하세요. 비워두면 이 슬롯은 건너뜁니다." style="font-size:12px;resize:vertical">${escAttr(cut.prompt)}</textarea>
          </div>
        </div>`;
    }).join('');
    const activeCount = cuts.filter(c => c && c.prompt && c.prompt.trim()).length;
    const modeNote = activeCount > 0
      ? `<span style="color:var(--ok)">✔ 프롬프트 ${activeCount}개 설정됨 — 실행 시 ${activeCount}개 이미지 생성</span>`
      : `<span style="color:var(--warn)">⚠ 프롬프트를 입력해야 실행됩니다</span>`;
    return `
      <div class="input-group" style="margin-top:14px">
        <label class="label" style="margin-bottom:8px">커스텀 프롬프트 (최대 10개)</label>
        <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin:0 0 10px">
          <p style="font-size:12px;margin:0">${modeNote}</p>
          <button type="button" class="btn-sm" id="serverRecoverCuts${modeId}" title="localStorage 백업과 이미지컷 마지막 프롬프트 기록에서 빈 슬롯을 복구합니다.">프롬프트 복구</button>
        </div>
        ${rows}
      </div>`;
  })() : '';

  const allEvents = (state.auto.serverStatus || state.auto.serverConfig?.status || {})?.recentEvents || [];

  return `
    <div class="auto-card" style="margin-top:10px">
      <h3 style="margin-bottom:10px">${title}</h3>
      <div class="input-group"><label class="label">입력 폴더 ID/URL</label><input class="input" id="serverInput${modeId}" value="${escAttr(profile.inputFolderId)}" placeholder="Drive folder ID or URL"></div>
      <div class="input-group"><label class="label">원본 완료 폴더 ID/URL</label><input class="input" id="serverDone${modeId}" value="${escAttr(profile.sourceDoneFolderId)}" placeholder="Drive folder ID or URL"></div>
      <div class="input-group"><label class="label">결과 출력 폴더 ID/URL</label><input class="input" id="serverOutput${modeId}" value="${escAttr(profile.outputFolderId)}" placeholder="Drive folder ID or URL"></div>
      <div style="display:grid;grid-template-columns:1fr 1fr 2fr 1fr;gap:10px;align-items:end">
        <div class="input-group"><label class="label">확인 간격(초)</label><input class="input" id="serverPoll${modeId}" type="number" min="30" max="3600" value="${escAttr(profile.pollIntervalSeconds)}"></div>
        <div class="input-group"><label class="label">한 번에 파일 수</label><input class="input" id="serverMax${modeId}" type="number" min="1" max="20" value="${escAttr(profile.maxFilesPerRun)}"></div>
        <div class="input-group"><label class="label">이미지 생성 모델</label><select class="input" id="serverModel${modeId}" style="height:38px">${modelOptions}</select></div>
        <div class="input-group"><label class="label">출력 해상도</label><select class="input" id="serverResolution${modeId}" style="height:38px">${buildResolutionOptions(profile.outputImageSize)}</select></div>
      </div>
      ${customCutsHtml}
      ${renderAutomationOutputPreview(mode)}
      <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:14px">
        <button class="btn-sm" id="serverSave${modeId}" title="${escAttr(title)} 설정 저장">${escapeHtml(title)} 저장</button>
        <button class="btn-sm" id="serverRun${modeId}" title="${escAttr(title)} 1회 즉시 실행" style="background:var(--accent,#b56d3a)">${escapeHtml(title)} 즉시 실행</button>
        <button class="btn-sm" id="serverAutoStart${modeId}" ${disabledAttr(autoEnabled, `${title} 자동화가 이미 실행 중입니다.`)} style="background:#2a7a3b">${escapeHtml(title)} 자동화 실행</button>
        <button class="btn-sm" id="serverAutoStop${modeId}" ${disabledAttr(!autoEnabled && !running, `${title} 자동화가 실행 중이 아닙니다.`)} style="background:#7a2a2a">${escapeHtml(title)} 자동화 중지</button>
      </div>
      <p id="autoStatusLine-${modeId}" style="font-size:12px;margin-top:8px;color:${autoStatusColor}">상태: ${autoStatusText}</p>
      <p id="autoSummaryLine-${modeId}" style="font-size:12px;color:var(--text-d);margin-top:4px">최근 요약: ${summary}</p>
      <p id="autoErrorLine-${modeId}" style="font-size:12px;color:var(--err);margin-top:4px;${error ? '' : 'display:none'}">${error ? '최근 오류: ' + escAttr(error) : ''}</p>
      <div style="margin-top:12px;background:var(--bg-input);border:1px solid var(--border);border-radius:8px;padding:10px">
        <div style="font-size:12px;font-weight:600;color:var(--text-m);margin-bottom:6px">작업 로그</div>
        <div id="autoLogBox-${modeId}" style="max-height:180px;overflow-y:auto">${buildEventLogInner(mode, status, allEvents)}</div>
      </div>
    </div>
  `;
}

