function getOptionTonePreset(id) {
  return OPTION_TONE_PRESETS.find(p => p.id === id) || OPTION_TONE_PRESETS[0];
}

function detectOptionTonePresetId(tone) {
  const normalized = String(tone || '').trim();
  const found = OPTION_TONE_PRESETS.find(p => p.tone === normalized);
  return found?.id || 'custom';
}

function getOptionToneDisplayName(os = state.optionSorter) {
  const presetId = os?.optionTonePresetId || detectOptionTonePresetId(os?.optionTone);
  const preset = presetId === 'custom' ? null : OPTION_TONE_PRESETS.find(p => p.id === presetId);
  return preset?.name || '직접 입력 톤';
}

