function getOptionPipelineId(os = state.optionSorter) {
  if ((os?.optionContentMode || 'full_image') === 'text_only') return 'text_only';
  if ((os?.optionSheetMethod || 'locked_canvas') === 'locked_canvas') return 'local_canvas';
  return (os?.optionContentMode || 'full_image') === 'mixed' ? 'ai_image_app_text' : 'ai_full_image';
}

