  const findFactoryCafe24CopyField = (fieldId) => factoryCafe24FormFieldsFlat().find(item =>
      item.id === fieldId ||
      item.dbFieldId === fieldId ||
      item.apiField === fieldId
    );
  const normalizeFactoryCopyValueForCafe24 = (fieldId, value) => {
    const field = findFactoryCafe24CopyField(fieldId);
    const apiField = field?.apiField || field?.id || fieldId;
    if (apiField && CAFE24_PRODUCT_JSON_PAYLOAD_FIELDS.has(apiField)) {
      const result = factoryCafe24StructuredJsonParseResult(apiField, value);
      if (result.needsReview) return value;
      if (result.payload !== undefined && result.payload !== null && (Array.isArray(result.payload) || typeof result.payload === 'object')) {
        return JSON.stringify(result.payload);
      }
    }
    return value;
  };
  const factoryCopyStructureMessageForCafe24 = (fieldId, value) => {
    const field = findFactoryCafe24CopyField(fieldId);
    const apiField = field?.apiField || field?.id || fieldId;
    if (!apiField || !CAFE24_PRODUCT_JSON_PAYLOAD_FIELDS.has(apiField)) return null;
    const result = factoryCafe24StructuredJsonParseResult(apiField, value);
    if (result.needsReview) {
      return {
        type: 'error',
        message: result.message || `${field?.label || fieldId} 값을 구조화하지 못했습니다. 원문을 보존했으니 GPT OAuth/수동 검수 후 저장해주세요.`,
      };
    }
    if (result.structured) {
      return {
        type: 'ok',
        message: `${field?.label || fieldId}: 구조화 가능한 값으로 분리해 Cafe24 입력칸에 반영했습니다.`,
      };
    }
    return null;
  };
  const factoryTryGptStructureForCafe24 = async (fieldId, value) => {
    const field = findFactoryCafe24CopyField(fieldId);
    const apiField = field?.apiField || field?.id || fieldId;
    if (!apiField || !CAFE24_PRODUCT_JSON_PAYLOAD_FIELDS.has(apiField)) return null;
    const parseResult = factoryCafe24StructuredJsonParseResult(apiField, value);
    if (!parseResult.needsReview) return null;
    const currentFactory = factoryRuntimeReadFactory();
    const currentTargetValue = field ? factoryCafe24StructuredValueForField(field, currentFactory) : null;
    const currentTargetText = currentTargetValue && (Array.isArray(currentTargetValue) || typeof currentTargetValue === 'object')
      ? factoryCafe24StructuredText(apiField, currentTargetValue)
      : String(currentTargetValue || '');
    try {
      await refreshGptOAuthStatus({ silent: true });
      if (!isGptOAuthConnected()) {
        return {
          value,
          type: 'error',
          message: `${field?.label || fieldId}: 규칙으로 구조화하지 못했고 GPT OAuth도 연결되지 않았습니다. 원문을 보존했으니 수동 검수해주세요.`,
        };
      }
      const cfg = normalizeModelConfig(state.modelConfig);
      const client = new GptOAuthAPI(cfg.llmModel, {
        reasoningEffort: cfg.gptOAuthReasoningEffort,
        serviceTier: cfg.gptOAuthServiceTier,
      });
      factoryLog(`${field?.label || fieldId}: 규칙 파싱 실패, GPT OAuth 구조화로 전환합니다.`, 'ok');
      const ai = await client.structureCafe24FieldValue({
        fieldId,
        apiField,
        label: field?.label || fieldId,
        value,
        currentTargetValue,
        currentTargetText,
      });
      const decision = String(ai?.decision || '').toLowerCase();
      const payload = ai?.payload;
      if (/structured|ok|success|완료|구조/.test(decision) && payload !== undefined && payload !== null && (Array.isArray(payload) || typeof payload === 'object')) {
        const aiCheck = factoryCafe24StructuredJsonParseResult(apiField, payload);
        if (aiCheck.needsReview) {
          return {
            value,
            type: 'error',
            message: `${field?.label || fieldId}: GPT OAuth 결과도 Cafe24 목표 스키마 검증을 통과하지 못했습니다. 원문을 보존했습니다.${ai?.reason ? ` (${ai.reason})` : ''}`,
          };
        }
        return {
          value: JSON.stringify(payload),
          type: 'ok',
          message: `${field?.label || fieldId}: GPT OAuth가 구조화했습니다. 저장 전 한 번 검수해주세요.${ai?.reason ? ` (${ai.reason})` : ''}`,
        };
      }
      return {
        value,
        type: 'error',
        message: `${field?.label || fieldId}: GPT OAuth도 확정 구조화를 보류했습니다. 원문을 보존했습니다.${ai?.reason ? ` (${ai.reason})` : ''}`,
      };
    } catch(e) {
      return {
        value,
        type: 'error',
        message: `${field?.label || fieldId}: GPT OAuth 구조화 실패 - ${formatAppErrorMessage(e.message || String(e))}`,
      };
    }
  };
