function factoryRenderAfterBackgroundStatusUpdate(options = {}) {
  if (state.projectBusy && state.workfileRestoreState) return;
  if (options.render !== false) render();
  return true;
}

function factoryStartCafe24OAuthAutoRefresh() {
  if (typeof startCafe24OAuthAutoRefresh !== 'function') return;
  const store = factoryRuntimeRequireStore();
  let operationToken = store.getOperationToken();
  let lastSignature = '';
  const commitStatus = (buildStatus, buildSignature, buildLog) => {
    if (!factoryRuntimeIsOperationCurrent(operationToken)) return false;
    const receipt = factoryRuntimeUpdateOwnedFactory(
      'factory/runtime:setCafe24OAuthAutoRefreshStatus',
      'product-db',
      draft => {
        draft.product = draft.product || {};
        const status = buildStatus(draft);
        const signature = buildSignature(status);
        const log = signature !== lastSignature ? buildLog(status) : null;
        draft.product.cafe24OAuthStatus = status;
        if (log) factoryLog(log.message, log.type, draft);
        return { signature, logged: !!log };
      },
    );
    operationToken = store.getOperationToken();
    if (receipt.result.logged) lastSignature = receipt.result.signature;
    factoryRenderAfterBackgroundStatusUpdate();
    return true;
  };
  startCafe24OAuthAutoRefresh({
    onStatus: status => commitStatus(
      () => status,
      nextStatus => [
        nextStatus.state,
        nextStatus.needsReauth === true,
        nextStatus.refreshWarning === true,
        nextStatus.refreshed === true,
        nextStatus.refreshState,
      ].join('|'),
      nextStatus => nextStatus.needsReauth || nextStatus.state === 'scope_required'
        ? { message: `Cafe24 OAuth 자동 점검: ${nextStatus.message}`, type: 'warn' }
        : nextStatus.refreshed
          ? { message: `Cafe24 OAuth access 토큰 자동 갱신 완료: ${nextStatus.mallId}`, type: 'ok' }
          : { message: `Cafe24 OAuth 자동 점검 완료: ${nextStatus.mallId} · ${nextStatus.message}`, type: 'info' },
    ),
    onError: error => {
      const message = error?.message || String(error || '알 수 없는 오류');
      const offline = typeof isCafe24ControlOfflineError === 'function' && isCafe24ControlOfflineError(error);
      return commitStatus(
        draft => {
          const previous = draft.product?.cafe24OAuthStatus || {};
          return {
            ...previous,
            state: offline ? 'offline' : 'unknown',
            needsReauth: false,
            mallId: String(previous.mallId || 'bojagi1928').trim(),
            checkedAt: Date.now(),
            message: offline
              ? 'Cafe24 Control Tower가 응답하지 않습니다. 자동 갱신을 다시 시도합니다.'
              : 'Cafe24 OAuth 자동 점검에 실패했습니다. 연결 상태를 다시 확인해주세요.',
            detail: String(message).slice(0, 360),
          };
        },
        status => `error|${status.state}|${status.detail}`,
        status => ({ message: `Cafe24 OAuth 자동 점검 실패: ${status.detail}`, type: 'error' }),
      );
    },
  });
}

let workspaceAuthorityUiLock = null;
let workspaceAuthorityUiDisposer = null;

function handleWorkspaceAuthorityAction(event) {
  const lock = workspaceAuthorityUiLock;
  const button = event.target?.closest?.('[data-workspace-authority-action]');
  if (!lock || !button || button.disabled) return;
  event.preventDefault();
  event.stopPropagation();
  const action = String(button.dataset.workspaceAuthorityAction || '');
  button.disabled = true;
  Promise.resolve().then(async () => {
    if (action === 'refresh') {
      await lock.refresh();
      return;
    }
    if (action === 'readonly') {
      await lock.release();
      lock.openReadOnly();
      return;
    }
    if (action === 'save-copy') {
      await startNewProjectDraft();
      await exportCurrentProjectFile({ saveAs: true });
      return;
    }
    if (action !== 'takeover') return;
    const authority = lock.snapshot();
    if (authority.mode === 'offline-edit' || /^draft:/i.test(String(authority.scopeId || ''))) {
      state.error = '로컬 초안은 서버 편집권 인계 대상이 아닙니다.';
      return;
    }
    const confirmed = window.confirm('다른 창의 저장 권한을 즉시 중지하고 이 창으로 편집권을 가져올까요?');
    if (!confirmed) return;
    await lock.takeover({
      confirmed: true,
      scopeId: lock.snapshot().scopeId,
      ownerId: workspaceAuthorityOwnerLabel(),
    });
  }).catch(error => {
    state.error = `작업 편집권 처리 실패: ${error?.message || error}`;
  }).finally(() => render());
}

function bindWorkspaceAuthorityUi() {
  if (workspaceAuthorityUiDisposer) return workspaceAuthorityUiDisposer;
  const lock = workspaceLockApi();
  if (!lock) return () => undefined;
  workspaceAuthorityUiLock = lock;
  let renderedSignature = '';
  let renderQueued = false;
  function queueAuthorityRender() {
    if (!workspaceAuthorityUiLock || (state.projectBusy && state.workfileRestoreState)) return;
    if (renderQueued) return;
    renderQueued = true;
    queueMicrotask(() => {
      renderQueued = false;
      if (!workspaceAuthorityUiLock || (state.projectBusy && state.workfileRestoreState)) return;
      render();
    });
  }
  function handleWorkspaceAuthoritySnapshot(snapshot) {
    const signature = [
      snapshot.scopeId, snapshot.mode, snapshot.ownerId, snapshot.reasonCode, snapshot.reason,
    ].join('|');
    if (signature === renderedSignature) return;
    renderedSignature = signature;
    queueAuthorityRender();
  }
  const unsubscribe = lock.subscribe(handleWorkspaceAuthoritySnapshot);
  document.addEventListener('click', handleWorkspaceAuthorityAction, true);
  workspaceAuthorityUiDisposer = () => {
    if (!workspaceAuthorityUiDisposer) return;
    document.removeEventListener('click', handleWorkspaceAuthorityAction, true);
    unsubscribe();
    workspaceAuthorityUiLock = null;
    workspaceAuthorityUiDisposer = null;
    renderedSignature = '';
    renderQueued = false;
  };
  return workspaceAuthorityUiDisposer;
}

