let classicRuntimeHydrationPromise = null;
let classicRuntimeLifecycleDisposer = null;
let classicRuntimeBackgroundDisposer = null;
let classicRuntimeGoogleAuthTimer = null;
let classicRuntimeCafe24OAuthTimer = null;

function classicRuntimeFreezeDetached(value) {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  for (const child of Object.values(value)) classicRuntimeFreezeDetached(child);
  return Object.freeze(value);
}

function classicRuntimeHydrationEnvelope(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError('classic runtime hydration envelope must be an object');
  }
  if (value.schema !== 'kuasangse.app-state') {
    throw new TypeError('classic runtime hydration schema must be kuasangse.app-state');
  }
  if (value.version !== 'app-state:v1') {
    throw new TypeError('classic runtime hydration version must be app-state:v1');
  }
  if (!value.state || typeof value.state !== 'object' || Array.isArray(value.state)) {
    throw new TypeError('classic runtime hydration state must be an object');
  }
  return classicRuntimeFreezeDetached({
    schema: value.schema,
    version: value.version,
    state: factoryRuntimeDetachedValue(value.state),
  });
}

function startClassicRuntimeBackgroundLifecycle() {
  if (classicRuntimeBackgroundDisposer) return classicRuntimeBackgroundDisposer;
  classicRuntimeGoogleAuthTimer = setTimeout(() => {
    classicRuntimeGoogleAuthTimer = null;
    try { initGoogleAuth(); } catch(e) {}
  }, 1000);
  classicRuntimeCafe24OAuthTimer = setTimeout(() => {
    classicRuntimeCafe24OAuthTimer = null;
    try {
      factoryStartCafe24OAuthAutoRefresh();
    } catch (error) {
      factoryLog(`Cafe24 OAuth 자동 갱신 초기화 실패: ${error?.message || error}`, 'error');
      render();
    }
  }, 1500);
  refreshGptOAuthStatus({ silent: true }).then(() => {
    if (state.step === 'analyzing' || state.step === 'modelsettings') render();
  }).catch(() => {});
  classicRuntimeBackgroundDisposer = () => {
    if (!classicRuntimeBackgroundDisposer) return;
    if (classicRuntimeGoogleAuthTimer !== null) clearTimeout(classicRuntimeGoogleAuthTimer);
    if (classicRuntimeCafe24OAuthTimer !== null) clearTimeout(classicRuntimeCafe24OAuthTimer);
    classicRuntimeGoogleAuthTimer = null;
    classicRuntimeCafe24OAuthTimer = null;
    if (typeof stopCafe24OAuthAutoRefresh === 'function') stopCafe24OAuthAutoRefresh();
    classicRuntimeBackgroundDisposer = null;
  };
  return classicRuntimeBackgroundDisposer;
}

function installClassicRuntimeLifecycle() {
  if (classicRuntimeLifecycleDisposer) return classicRuntimeLifecycleDisposer;
  const disposeListeners = bindClassicRuntimeListeners();
  const disposeBackground = startClassicRuntimeBackgroundLifecycle();
  classicRuntimeLifecycleDisposer = () => {
    if (!classicRuntimeLifecycleDisposer) return;
    disposeBackground();
    disposeListeners();
    classicRuntimeLifecycleDisposer = null;
  };
  return classicRuntimeLifecycleDisposer;
}

function disposeClassicRuntimeLifecycle() {
  if (classicRuntimeLifecycleDisposer) classicRuntimeLifecycleDisposer();
}

async function reloadAcceptedWorkspace(accepted) {
  const takeoverAuthority = workspaceTakeoverHydrationAuthority.create(accepted);
  try {
    return await hydrateServerLastWorkSnapshot({
      force: true,
      forceStep: true,
      takeoverSync: true,
      minimumRevision: takeoverAuthority.identity.revision,
      takeoverAuthority,
    });
  } finally {
    takeoverAuthority.close();
  }
}

async function runClassicRuntimeHydration(envelope) {
  installClassicRuntimeLifecycle();
  try {
    if (hasGeminiConnection()) gemini = createGeminiClient();
    const hydrationWorkspaceScope = getCurrentLastWorkWorkspaceScope();
    const hydrationProjectId = String(state.currentProjectId || '').trim();
    const hydrationIdentityIsCurrent = () => getCurrentLastWorkWorkspaceScope() === hydrationWorkspaceScope
      && String(state.currentProjectId || '').trim() === hydrationProjectId;
    const hydrationResult = stale => Object.freeze({
      schema: envelope.schema,
      version: envelope.version,
      hydrated: true,
      stale,
    });
    const initialWorkspaceAuthority = hydrationIdentityIsCurrent()
      ? ensureWorkspaceEditAuthority(hydrationWorkspaceScope).catch(() => null)
      : Promise.resolve(null);
    try { markSessionAssetFingerprintSaved(); } catch(e) {}
    loadCutsArchiveFolderStatus({ render: false }).catch(() => {});
    refreshWorkspaceLists().catch(() => {});
    await hydratePersistentSessionAssets().catch(() => {});
    await initialWorkspaceAuthority;
    if (!hydrationIdentityIsCurrent()) return hydrationResult(true);
    await ensureWorkspaceEditAuthority(hydrationWorkspaceScope).catch(() => null);
    if (!hydrationIdentityIsCurrent()) return hydrationResult(true);
    await hydrateServerLastWorkSnapshot().catch(() => {});
    if (typeof factoryRestoreCurrentWorkfileLocalArchive === 'function') {
      await factoryRestoreCurrentWorkfileLocalArchive({ silent: true }).catch(() => null);
    }
    const factoryProduct = state.factory?.product || {};
    const hasProductWork = !!(
      state.productName ||
      state.imageBase64 ||
      (state.imagePreview && state.imagePreview !== '__stored_in_indexeddb__') ||
      factoryProduct.productName ||
      factoryProduct.imageBase64 ||
      (factoryProduct.imagePreview && factoryProduct.imagePreview !== '__stored_in_indexeddb__') ||
      factoryProduct.hasImage
    );
    if (hasProductWork && typeof hydrateLastProductImageBackup === 'function') {
      await hydrateLastProductImageBackup({ restoreInline: true }).catch(() => false);
    }
    await new Promise(resolve => setTimeout(resolve, 0));
    if (factoryRuntimeStore) factoryRuntimeHydrateStoreFromBootstrap();
    return hydrationResult(false);
  } catch (error) {
    disposeClassicRuntimeLifecycle();
    throw error;
  }
}

function hydrateClassicRuntime(envelope) {
  const detachedEnvelope = classicRuntimeHydrationEnvelope(envelope);
  if (!classicRuntimeHydrationPromise) {
    classicRuntimeHydrationPromise = runClassicRuntimeHydration(detachedEnvelope);
  }
  return classicRuntimeHydrationPromise;
}

function shouldSkipGlobalLastWorkInputSave(target, eventType = 'input') {
  if (!target || typeof target.closest !== 'function') return false;
  if (target.closest('[data-factory-wizard-field], #factoryWizardMissingFieldsPanel')) return true;
  if (eventType === 'input' && target.closest('.factory-page')) return true;
  if (eventType === 'input' && target.closest('#factoryAutomationPanel')) return true;
  return false;
}
function handleClassicRuntimeInput(event) {
  const target = event.target;
  if (!target || typeof target.matches !== 'function') return;
  const isEditableTarget = target.matches('input, textarea, select') || target.isContentEditable;
  if (!isEditableTarget) return;
  if (shouldSkipGlobalLastWorkInputSave(target, 'input')) return;
  if (typeof markLastWorkInteractiveInput === 'function') {
    markLastWorkInteractiveInput(target, 'input');
  }
  if (isEditableTarget) {
    if (typeof markLastWorkInteractiveInput === 'function') {
      scheduleLastWorkSave(900, { lightweight: true });
    } else {
      scheduleLastWorkSave(900, { lightweight: true });
    }
  }
}

function handleClassicRuntimeChange(event) {
  const target = event.target;
  if (!target || typeof target.matches !== 'function') return;
  const isEditableTarget = target.matches('input, textarea, select') || target.isContentEditable;
  if (!isEditableTarget) return;
  if (shouldSkipGlobalLastWorkInputSave(target, 'change')) return;
  if (typeof markLastWorkInteractiveInput === 'function') {
    markLastWorkInteractiveInput(target, 'change');
  }
  if (isEditableTarget) {
    if (typeof markLastWorkInteractiveInput === 'function') {
      saveLastWorkNow({ interactive: true });
    } else {
      saveLastWorkNow({ interactive: true });
    }
  }
}

function handleCompMarketQuickActionClick(event) {
    const button = event.target?.closest?.([
      '[data-comp-market-quick-action]',
      '[data-comp-market-toggle-result]',
      '[data-comp-market-source-view]',
      '#compMarketStart',
      '#compMarketStartLocal',
      '#compMarketReloadSearchResults',
      '#compMarketDetailSelected',
      '#compMarketDetailSelectedMain',
      '#compMarketDetailSelectedVm',
      '#compMarketDetailSelectedLocal',
      '#compMarketDetailSelectedLocalMain',
      '#compMarketVmAnalyze',
      '#compMarketVmAnalyzeMain',
      '#compMarketDetailSelectedAnalyzeVm',
      '#compMarketSelectAllCandidates',
      '#compMarketClearCandidateSelection',
    ].join(','));
    if (!button || button.disabled || button.getAttribute('aria-disabled') === 'true') return;
    if (typeof button.onclick === 'function') return;

    const legacyActionById = {
      compMarketStart: 'start-vm',
      compMarketStartLocal: 'start-local',
      compMarketReloadSearchResults: 'reload',
      compMarketDetailSelected: 'detail-vm',
      compMarketDetailSelectedMain: 'detail-vm',
      compMarketDetailSelectedVm: 'detail-vm',
      compMarketDetailSelectedLocal: 'detail-local',
      compMarketDetailSelectedLocalMain: 'detail-local',
      compMarketVmAnalyze: 'analyze-vm',
      compMarketVmAnalyzeMain: 'analyze-vm',
      compMarketDetailSelectedAnalyzeVm: 'analyze-vm',
      compMarketSelectAllCandidates: 'select-all',
      compMarketClearCandidateSelection: 'clear-selection',
    };
    let action = String(button.dataset.compMarketQuickAction || legacyActionById[button.id] || '');
    if (!action && button.dataset.compMarketToggleResult) action = 'toggle-selection';
    if (!action && button.dataset.compMarketSourceView) action = 'source-view';
    const handledActions = [
      'start-vm', 'start-local', 'reload', 'detail-vm', 'detail-local', 'analyze-vm',
      'select-all', 'clear-selection', 'select-all-images', 'clear-images', 'toggle-history-images', 'toggle-selection', 'source-view',
    ];
    if (!handledActions.includes(action)) return;

    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();

    const runAction = () => {
      if (action === 'start-vm') {
        return typeof factoryRunVmCompetitorCollectionForSelection === 'function'
          ? factoryRunVmCompetitorCollectionForSelection()
          : runCompMarketScrape('vm');
      }
      if (action === 'start-local') {
        if (typeof compMarketConfirmLocalCandidateCollection === 'function' && !compMarketConfirmLocalCandidateCollection()) return;
        return runCompMarketScrape('local');
      }
      if (action === 'reload') return reloadCompMarketSearchResultsFromCurrentId();
      if (action === 'detail-vm') return runCompMarketDetailCapture();
      if (action === 'detail-local') return runCompMarketDetailCapture(null, { runtime: 'local' });
      if (action === 'analyze-vm') return runCompMarketDetailCaptureAndAnalyze();
      if (action === 'source-view') return compMarketSetCandidateSourceView(button.dataset.compMarketSourceView);

      const market = ensureCompMarketScrapeState();
      if (action === 'toggle-selection') {
        const id = String(button.dataset.compMarketToggleResult || '');
        if (!id) return;
        const set = new Set(market.selectedIds || []);
        if (set.has(id)) set.delete(id);
        else set.add(id);
        market.selectedIds = Array.from(set);
        compMarketMarkDetailSelectionChanged(market, '선택 후보가 바뀌었습니다. 이전 상세수집 결과는 현재 선택에 섞지 않습니다.');
      } else if (action === 'select-all') {
        const candidates = typeof compMarketAllCandidateResults === 'function'
          ? compMarketAllCandidateResults(market)
          : (market.results || []);
        market.results = candidates;
        market.selectedIds = candidates.map((item, index) => compMarketResultId(item, index));
        compMarketMarkDetailSelectionChanged(market, '후보 전체 선택으로 상세수집 선택 범위가 바뀌었습니다.');
      } else if (action === 'clear-selection') {
        market.selectedIds = [];
        compMarketMarkDetailSelectionChanged(market, '후보 선택을 해제해 이전 상세수집 결과를 현재 선택에 섞지 않습니다.');
      } else if (action === 'select-all-images') {
        const images = typeof compMarketCurrentDetailImages === 'function'
          ? compMarketCurrentDetailImages(market).currentImages
          : compMarketDedupeScrapedImages(market.scrapedImages || [], market);
        market.selectedImageIds = images.map((img, index) => compMarketScrapedImageId(img, index));
        compMarketMarkSelectionChanged('이번 선택으로 수집한 상세페이지 이미지를 분석 대상으로 선택했습니다.');
      } else if (action === 'clear-images') {
        market.selectedImageIds = [];
        compMarketMarkSelectionChanged('상세페이지 이미지 선택을 해제했습니다.');
      } else if (action === 'toggle-history-images') {
        market.showPreviousDetailImages = !market.showPreviousDetailImages;
      }
      market.lastUpdatedAt = Date.now();
      saveCompMarketUiState();
      render();
    };

    Promise.resolve(runAction()).catch(error => {
      const message = error?.message || String(error || '알 수 없는 오류');
      compMarketLog(`경쟁사 빠른 실행 실패: ${message}`, 'error');
      compMarketSetStatus(`경쟁사 빠른 실행 실패: ${message}`, 'quick-action', 'error');
      render();
    });
}

function handleFactoryGenerationFallbackClick(event) {
  const target = event.target;
  if (!target || typeof target.closest !== 'function') return;

  const factoryAnalyzeImageBtn = target.closest('#factoryAnalyzeCurrentImage');
  if (factoryAnalyzeImageBtn) {
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();
    if (!factoryAnalyzeImageBtn.disabled && typeof factoryRunCurrentProductImageAnalysisOnly === 'function') {
      Promise.resolve(factoryRunCurrentProductImageAnalysisOnly()).catch(error => {
        factoryLog(`현재 이미지 AI 분석 실행 실패: ${error?.message || error}`, 'error');
        saveLastWorkNow();
        render();
      });
    }
    return;
  }

  const factoryRunDbBtn = target.closest('#factoryRunDb');
  if (factoryRunDbBtn) {
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();
    if (!factoryRunDbBtn.disabled && typeof factoryRunDbCompetitorHeroCutsFlow === 'function') {
      Promise.resolve(factoryRunDbCompetitorHeroCutsFlow()).catch(error => {
        factoryLog(`DB/경쟁사·제품분석·이미지 생성 실행 실패: ${error?.message || error}`, 'error');
        saveLastWorkNow();
        render();
      });
    }
    return;
  }

  const sizeBtn = target.closest('[data-gen-size-cut]');
  if (sizeBtn) {
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();
    const idx = Number.parseInt(sizeBtn.dataset.genSizeCut, 10);
    if (Number.isFinite(idx)) generateSizeCut(idx);
    return;
  }

  const allSizeBtn = target.closest('#genAllSizeCutsBtn');
  if (allSizeBtn) {
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();
    generateAllSizeCuts();
    return;
  }

  const cutBtn = target.closest('[data-gen-cut]');
  if (cutBtn) {
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();
    const idx = Number.parseInt(cutBtn.dataset.genCut, 10);
    if (Number.isFinite(idx)) generateCut(idx);
    return;
  }

  const allCutsBtn = target.closest('#genAllCutsBtn');
  if (allCutsBtn) {
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();
    generateAllCuts();
  }
}

function handleClassicRuntimeVisibilityChange() {
  if (document.visibilityState === 'hidden') flushLastWorkBeforeLeave();
}

let classicRuntimeListenersBound = false;
let classicRuntimeListenersDisposer = null;

function bindClassicRuntimeDocumentEvents() {
  document.addEventListener('error', handleFactoryRenderedImageErrorEvent, true);
  document.addEventListener('input', handleClassicRuntimeInput, true);
  document.addEventListener('change', handleClassicRuntimeChange, true);
  document.addEventListener('click', handleCompMarketQuickActionClick, true);
  document.addEventListener('click', handleFactoryGenerationFallbackClick, true);
  window.addEventListener('beforeunload', flushLastWorkBeforeLeave);
  window.addEventListener('pagehide', flushLastWorkBeforeLeave);
  document.addEventListener('visibilitychange', handleClassicRuntimeVisibilityChange);
  return () => {
    document.removeEventListener('error', handleFactoryRenderedImageErrorEvent, true);
    document.removeEventListener('input', handleClassicRuntimeInput, true);
    document.removeEventListener('change', handleClassicRuntimeChange, true);
    document.removeEventListener('click', handleCompMarketQuickActionClick, true);
    document.removeEventListener('click', handleFactoryGenerationFallbackClick, true);
    window.removeEventListener('beforeunload', flushLastWorkBeforeLeave);
    window.removeEventListener('pagehide', flushLastWorkBeforeLeave);
    document.removeEventListener('visibilitychange', handleClassicRuntimeVisibilityChange);
  };
}

function bindClassicRuntimeListeners() {
  if (classicRuntimeListenersBound) return classicRuntimeListenersDisposer;
  const disposers = [
    bindFactoryLocalArchivePreviewDelegation(),
    bindFactoryCandidateReviewDelegation(),
    bindOptionSorterPreviewDelegation(),
    bindClassicRuntimeDocumentEvents(),
    bindWorkspaceAuthorityUi(),
  ].filter(dispose => typeof dispose === 'function');
  classicRuntimeListenersBound = true;
  classicRuntimeListenersDisposer = () => {
    if (!classicRuntimeListenersBound) return;
    for (const dispose of disposers.reverse()) dispose();
    classicRuntimeListenersBound = false;
    classicRuntimeListenersDisposer = null;
  };
  return classicRuntimeListenersDisposer;
}



